# Seva team decision (Oct 2026): "Temporarily unavailable" is now "On Hold" and
# "Do not call" is no longer used (those Saints become Inactive).
RENAMED = {"temp_unavailable": "on_hold", "do_not_call": "inactive"}


def rename_statuses(apps, schema_editor):
    Contact = apps.get_model("contacts", "Contact")
    Change = apps.get_model("contacts", "ContactStatusChange")
    for old, new in RENAMED.items():
        Contact.objects.filter(status=old).update(status=new)
